localStorage.removeItem('fixture-node-config:nodes:fixture.node-config');
createRoot(document.getElementById('root')).render(<Fixture />);
const tick = (ms=250) => new Promise((resolve) => setTimeout(resolve, ms));
const checks = document.getElementById('checks'); let failed = false;
