const select = async (id) => { document.querySelector(`.react-flow__node[data-id="${id}"]`).dispatchEvent(new MouseEvent('click', { bubbles: true })); await tick(500); };
const openSelect = async (label) => {
  const trigger = document.querySelector(`button[role="combobox"][aria-label="${label}"]`);
  trigger.focus(); trigger.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowDown', bubbles: true })); await tick();
  return trigger;
};
const change = async (label, value) => {
  await openSelect(label);
  const option = document.querySelector(`[role="option"][data-value="value:${value}"]`);
  if (!option) throw new Error(`Missing ${label} option: ${value}`);
  option.focus(); option.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true })); await tick();
};
