  await select('verifier'); await change('Node provider', 'b'); await tick(500); await change('Node thinking level', 'low');
  check(window.__configs.worker.model_id === 'model-a2' && window.__configs.verifier.model_id === 'model-b', 'Same agent nodes use independent models');
  check(document.querySelector('.react-flow__node[data-id="worker"] .workflow-node-model')?.textContent.includes('model-a2') && document.querySelector('.react-flow__node[data-id="verifier"] .workflow-node-model')?.textContent.includes('model-b'), 'Canvas shows each node’s independent provider/model selection');
  check(window.__configs.worker.reasoning_effort === 'high' && window.__configs.verifier.reasoning_effort === 'low', 'Thinking is independently configured per node');
  await select('worker'); check(document.querySelector('button[aria-label="Node model"]').textContent.includes('model-a2'), 'Switching node preserves selection');
  check(JSON.parse(localStorage.getItem('fixture-node-config:nodes:fixture.node-config')).worker.model_id === 'model-a2', 'Node selection persisted by workflow');
  window.__running(true); await tick(); check([...document.querySelectorAll('.workflow-runtime-config button[role="combobox"]')].every((element) => element.disabled), 'Active run config is read only');
  check(!document.querySelector('#stage .context-usage-btn') && !document.querySelector('#stage .model-picker'), 'Bot has no context or model picker');
  check(document.querySelector('#stage button[role="combobox"][aria-label="Workflow"]')?.disabled, 'Workflow picker uses shared custom Select and is locked while running');
  check(document.querySelector('#chat .context-usage-btn') && document.querySelector('#chat .model-picker'), 'Chat context and model picker unchanged');
